2	import { cookies } from 'next/headers';
3	import { redirect } from 'next/navigation';
4	import Link from 'next/link';
5	import { getSession } from '@/lib/session';
6	import { CATEGORY_LABELS, STATUS_CONFIG, CATEGORY_COLORS } from '@/lib/constants';
7	import type { EmailCategory, EmailStatus, ProcessedEmail, Email } from '@/lib/types';
8	
9	// STATUS ordering for display
10	const STATUS_ORDER: EmailStatus[] = ['NEEDS_ACTION', 'PENDING', 'RESPONDED', 'INFO_ONLY'];
11	
12	// Map STALE freshness to a display group
13	const STALE_LABEL = 'STALE';
14	
15	type StatusGroup = EmailStatus | typeof STALE_LABEL;
16	
17	interface EmailRow {
18	  email: Email;
19	  processed: ProcessedEmail;
20	  statusGroup: StatusGroup;
21	}
22	
23	function groupByStatus(rows: EmailRow[]): Record<StatusGroup, EmailRow[]> {
24	  const groups: Record<string, EmailRow[]> = {};
25	  for (const row of rows) {
26	    const key = row.statusGroup;
27	    if (!groups[key]) groups[key] = [];
28	    groups[key].push(row);
29	  }
30	  return groups as Record<StatusGroup, EmailRow[]>;
31	}
32	
33	const STATUS_GROUPS_ORDER: StatusGroup[] = ['NEEDS_ACTION', 'PENDING', 'RESPONDED', 'INFO_ONLY', STALE_LABEL];
34	
35	function StatusBadge({ status }: { status: StatusGroup }) {
36	  if (status === STALE_LABEL) {
37	    return (
38	      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-500">
39	        🕳️ Stale
40	      </span>
41	    );
42	  }
43	  const cfg = STATUS_CONFIG[status];
44	  if (!cfg) return null;
45	  return (
46	    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium ${cfg.color}`}>
47	      {cfg.emoji} {cfg.label}
48	    </span>
49	  );
50	}
51	
52	function EmailListItem({
53	  row,
54	  href,
55	}: {
56	  row: EmailRow;
57	  href: string;
58	}) {
59	  const isStale = row.statusGroup === STALE_LABEL;
60	  const days = row.processed.daysWithoutReply;
61	  return (
62	    <Link href={href}>
63	      <div
64	        className={`flex items-center justify-between p-3 rounded-lg hover:bg-gray-100 transition-colors cursor-pointer border border-gray-200 ${isStale ? 'opacity-50' : ''}`}
65	      >
66	        <div className="min-w-0 flex-1">
67	          <p className="text-sm font-medium truncate text-gray-900">
68	            {row.email.fromName || row.email.fromEmail || row.email.from}
69	          </p>
70	          <p className="text-xs text-gray-500 truncate">{row.email.subject}</p>
71	        </div>
72	        <div className="flex items-center gap-2 shrink-0 ml-3">
73	          <StatusBadge status={row.statusGroup} />
74	          {days !== null && days > 0 && !isStale && row.processed.status === 'NEEDS_ACTION' && (
75	            <span className="text-xs text-red-600 font-medium">{days}d</span>
76	          )}
77	        </div>
78	      </div>
79	    </Link>
80	  );
81	}
82	
83	function CategorySection({
84	  category,
85	  rows,
86	  totalCount,
87	}: {
88	  category: EmailCategory;
89	  rows: EmailRow[];
90	  totalCount: number;
91	}) {
92	  const grouped = groupByStatus(rows);
93	  const colorClass = CATEGORY_COLORS[category] || 'bg-gray-100 text-gray-800';
94	
95	  return (
96	    <details className="border border-gray-200 rounded-lg overflow-hidden">
97	      <summary className="flex items-center justify-between px-4 py-3 bg-white cursor-pointer hover:bg-gray-50 list-none">
98	        <span className="font-medium text-gray-800">
99	          {CATEGORY_LABELS[category] || category}
100	        </span>
101	        <span className={`ml-2 px-2 py-0.5 rounded text-xs font-semibold ${colorClass}`}>
102	          {totalCount}
103	        </span>
104	      </summary>
105	      <div className="bg-white px-4 pb-4 space-y-4">
106	        {STATUS_GROUPS_ORDER.map((statusGroup) => {
107	          const groupRows = grouped[statusGroup];
108	          if (!groupRows || groupRows.length === 0) return null;
109	          const isStaleGroup = statusGroup === STALE_LABEL;
110	          const groupLabel =
111	            statusGroup === STALE_LABEL
112	              ? '🕳️ Stale'
113	              : `${STATUS_CONFIG[statusGroup]?.emoji || ''} ${STATUS_CONFIG[statusGroup]?.label || statusGroup}`;
114	          return (
115	            <div key={statusGroup}>
116	              <p className={`text-xs font-semibold uppercase tracking-wide mb-2 mt-3 ${isStaleGroup ? 'text-gray-400' : 'text-gray-600'}`}>
117	                {groupLabel} ({groupRows.length})
118	              </p>
119	              <div className="space-y-1">
120	                {groupRows.map((row) => {
121	                  let href = '#';
122	                  if (category === 'CARGO_INQUIRY') href = `/cargo/${row.email.id}`;
123	                  else if (category === 'VESSEL_POSITION') href = `/vessel/${row.email.id}`;
124	                  else if (category === 'FIXTURE_RECAP') href = `/fixture/${row.email.id}`;
125	                  else href = `/cargo/${row.email.id}`;
126	                  return <EmailListItem key={row.email.id} row={row} href={href} />;
127	                })}
128	              </div>
129	            </div>
130	          );
131	        })}
132	        {rows.length === 0 && (
133	          <p className="text-sm text-gray-400 pt-2">No emails in this category.</p>
134	        )}
135	      </div>
136	    </details>
137	  );
138	}
139	
140	export default async function DashboardPage() {
141	  const cookieStore = await cookies();
142	  const sessionId = cookieStore.get('session_id')?.value;
143	  if (!sessionId) redirect('/');
144	
145	  const session = getSession(sessionId);
146	  if (!session) redirect('/');
147	
148	  const {
149	    emails,
150	    processedEmails,
151	    matches,
152	    recaps,
153	    commissionSummary,
154	    counterparties,
155	    parsedFixtureRecaps,
156	  } = session;
157	
158	  // Build a map: emailId -> ProcessedEmail
159	  const processedMap = new Map<string, ProcessedEmail>();
160	  for (const pe of processedEmails) {
161	    processedMap.set(pe.emailId, pe);
162	  }
163	
164	  // Build a map: emailId -> Email
165	  const emailMap = new Map<string, Email>();
166	  for (const e of emails) {
167	    emailMap.set(e.id, e);
168	  }
169	
170	  // Build EmailRow list
171	  function buildRows(category: EmailCategory): EmailRow[] {
172	    const rows: EmailRow[] = [];
173	    for (const pe of processedEmails) {
174	      if (pe.type !== category) continue;
175	      const email = emailMap.get(pe.emailId);
176	      if (!email) continue;
177	      const isStale = pe.freshness === 'stale';
178	      const statusGroup: StatusGroup = isStale ? STALE_LABEL : pe.status;
179	      rows.push({ email, processed: pe, statusGroup });
180	    }
181	    // Sort: NEEDS_ACTION first, then PENDING, RESPONDED, INFO_ONLY, STALE
182	    rows.sort((a, b) => {
183	      const orderA = STATUS_GROUPS_ORDER.indexOf(a.statusGroup);
184	      const orderB = STATUS_GROUPS_ORDER.indexOf(b.statusGroup);
185	      if (orderA !== orderB) return orderA - orderB;
186	      // Within NEEDS_ACTION, sort by daysWithoutReply desc
187	      if (a.statusGroup === 'NEEDS_ACTION') {
188	        return (b.processed.daysWithoutReply || 0) - (a.processed.daysWithoutReply || 0);
189	      }
190	      return 0;
191	    });
192	    return rows;
193	  }
194	
195	  const cargoRows = buildRows('CARGO_INQUIRY');
196	  const vesselRows = buildRows('VESSEL_POSITION');
197	  const fixtureRows = buildRows('FIXTURE_RECAP');
198	  const clientReplyRows = buildRows('CLIENT_REPLY');
199	  const documentRows = buildRows('DOCUMENT');
200	  const otherOnlyRows = buildRows('OTHER');
201	  const otherRows = [
202	    ...clientReplyRows,
203	    ...documentRows,
204	    ...otherOnlyRows,
205	  ];
206	
207	  // Action block: unanswered inquiries
208	  const needsActionCargo = cargoRows.filter((r) => r.statusGroup === 'NEEDS_ACTION');
209	  const oldestDays =
210	    needsActionCargo.length > 0
211	      ? Math.max(...needsActionCargo.map((r) => r.processed.daysWithoutReply || 0))
212	      : 0;
213	
214	  // Good/possible matches
215	  const goodMatches = matches.filter((m) => m.matchLevel === 'good' || m.matchLevel === 'possible');
216	
217	  // Commission totals
218	  const commissionLines =
219	    commissionSummary?.totalByCurrency
220	      .map((t) => `~${t.currency} ${t.amount.toLocaleString(undefined, { maximumFractionDigits: 0 })}`)
221	      .join(' + ') || null;
222	
223	  // Active negotiations (recaps)
224	  const activeRecaps = recaps;
225	
226	  // Category counts (all statuses including stale)
227	  const categoryCounts: Record<string, number> = {
228	    CARGO_INQUIRY: cargoRows.length,
229	    VESSEL_POSITION: vesselRows.length,
230	    FIXTURE_RECAP: fixtureRows.length,
231	    CLIENT_REPLY: clientReplyRows.length,
232	    DOCUMENT: documentRows.length,
233	    OTHER: otherOnlyRows.length,
234	  };
235	
236	  const isSample = session.isSampleData === true;
237	
238	  // Compute top contacts from emails (grouped by fromEmail)
239	  const senderMap = new Map<string, { name: string; count: number }>();
240	  for (const email of emails) {
241	    const key = (email.fromEmail || email.from || '').toLowerCase().trim();
242	    if (!key) continue;
243	    const existing = senderMap.get(key);
244	    if (existing) {
245	      existing.count += 1;
246	    } else {
247	      senderMap.set(key, { name: email.fromName || email.fromEmail || email.from || key, count: 1 });
248	    }
249	  }
250	  const topContacts = Array.from(senderMap.values())
251	    .sort((a, b) => b.count - a.count)
252	    .slice(0, 10);
253	  const maxContactEmails = topContacts.length > 0 ? topContacts[0].count : 1;
254	
255	  return (
256	    <main className="min-h-screen bg-gray-50 py-8 px-4">
257	      <div className="max-w-3xl mx-auto space-y-6">
258	        {/* Header */}
259	        <div>
260	          <h1 className="text-xl font-bold text-gray-900">
261	            Good morning. Here&apos;s what needs your attention:
262	          </h1>
263	          <p className="text-sm text-gray-500 mt-1">{emails.length} emails processed</p>
264	          {isSample && (
265	            <span className="inline-block mt-1 px-2 py-0.5 rounded text-xs font-medium bg-yellow-100 text-yellow-800">
266	              Sample data
267	            </span>
268	          )}
269	        </div>
270	
271	        {/* ── ACTION BLOCKS ── */}
272	        <div className="space-y-3">
273	          {/* Unanswered inquiries */}
274	          {needsActionCargo.length > 0 ? (
275	            <details className="rounded-lg border bg-red-50 border-red-200 overflow-hidden">
276	              <summary className="flex items-center gap-3 p-4 cursor-pointer hover:bg-red-100 list-none">
277	                <span className="text-2xl">🔴</span>
278	                <div className="flex-1">
279	                  <p className="font-semibold text-red-800">
280	                    {needsActionCargo.length} {needsActionCargo.length === 1 ? 'inquiry' : 'inquiries'} waiting for your reply
281	                  </p>
282	                  {oldestDays > 0 && (
283	                    <p className="text-sm text-red-600">Oldest: {oldestDays} days without reply · tap to expand</p>
284	                  )}
285	                </div>
286	                <span className="shrink-0 text-red-400 text-sm">▼</span>
287	              </summary>
288	              <div className="bg-white px-4 pb-4 pt-2 space-y-1">
289	                {needsActionCargo.map((row) => (
290	                  <EmailListItem key={row.email.id} row={row} href={`/cargo/${row.email.id}`} />
291	                ))}
292	              </div>
293	            </details>
294	          ) : (
295	            <div className="flex items-center p-4 rounded-lg border bg-white border-gray-200">
296	              <span className="text-2xl mr-3">🔴</span>
297	              <p className="font-medium text-gray-600">No unanswered inquiries — all clear</p>
298	            </div>
299	          )}
300	
301	          {/* Matches */}
302	          {goodMatches.length > 0 ? (
303	            <details className="rounded-lg border bg-blue-50 border-blue-200 overflow-hidden">
304	              <summary className="flex items-center gap-3 p-4 cursor-pointer hover:bg-blue-100 list-none">
305	                <span className="text-2xl">🔗</span>
306	                <div className="flex-1">
307	                  <p className="font-semibold text-blue-800">
308	                    {goodMatches.length} vessel-cargo {goodMatches.length === 1 ? 'match' : 'matches'} found
309	                  </p>
310	                  <p className="text-sm text-blue-600">tap to expand</p>
311	                </div>
312	                <span className="shrink-0 text-blue-400 text-sm">▼</span>
313	              </summary>
314	              <div className="bg-white px-4 pb-4 pt-2 space-y-1">
315	                {goodMatches.map((match, i) => (
316	                  <Link key={i} href={`/match/${i}`}>
317	                    <div className="flex items-center justify-between p-3 rounded-lg hover:bg-gray-100 transition-colors cursor-pointer border border-gray-200 bg-white">
318	                      <div className="min-w-0 flex-1">
319	                        <p className="text-sm font-medium text-gray-900 truncate">
320	                          {match.matchReasons[0] || `Match #${i + 1}`}
321	                        </p>
322	                        <p className="text-xs text-gray-500">
323	                          Level: {match.matchLevel} · {match.matchReasons.length} reasons
324	                        </p>
325	                      </div>
326	                      <span className={`shrink-0 ml-3 px-2 py-0.5 rounded text-xs font-semibold ${match.matchLevel === 'good' ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'}`}>
327	                        {match.matchLevel}
328	                      </span>
329	                    </div>
330	                  </Link>
331	                ))}
332	              </div>
333	            </details>
334	          ) : (
335	            <div className="flex items-center p-4 rounded-lg border bg-white border-gray-200">
336	              <span className="text-2xl mr-3">🔗</span>
337	              <p className="font-medium text-gray-500">No vessel-cargo matches found</p>
338	            </div>
339	          )}
340	
341	          {/* Fixture recaps */}
342	          {fixtureRows.length > 0 ? (
343	            <details className="rounded-lg border bg-purple-50 border-purple-200 overflow-hidden">
344	              <summary className="flex items-center gap-3 p-4 cursor-pointer hover:bg-purple-100 list-none">
345	                <span className="text-2xl">📋</span>
346	                <div className="flex-1">
347	                  <p className="font-semibold text-purple-800">
348	                    {fixtureRows.length} fixture {fixtureRows.length === 1 ? 'recap' : 'recaps'} extracted
349	                  </p>
350	                  <p className="text-sm text-purple-600">tap to expand</p>
351	                </div>
352	                <span className="shrink-0 text-purple-400 text-sm">▼</span>
353	              </summary>
354	              <div className="bg-white px-4 pb-4 pt-2 space-y-1">
355	                {fixtureRows.map((row) => (
356	                  <EmailListItem key={row.email.id} row={row} href={`/fixture/${row.email.id}`} />
357	                ))}
358	              </div>
359	            </details>
360	          ) : (
361	            <div className="flex items-center p-4 rounded-lg border bg-white border-gray-200">
362	              <span className="text-2xl mr-3">📋</span>
